    OUT["PTM-A"] = {"b": hex(b), "redraws": redraws, "#E_b": Nb, "factorisation": {str(p): e for p, e in fb.items()},
                    "r": rb, "d_min": dmin, "k": kA, "tau(P)_on_E_b": tau_on, "W": "ker f1(tau), first stable W",
                    "|F_W|": len(cellA.FW), "ghat_f1(1)=weight(f1) mod r": bin(g).count("1") % rb,
                    "deg_h_g_at_k=1": 0 if bin(g).count("1") % rb else 1,
                    "relations": len(relsA), "readout": tallyA}

    run_ptm_b(F, E, r, h, lam, cell, Wb, P0, 17, "n17-a0")
    F23, E23, r23_, h23, lam23, c23, W23, Wb23, g23, P023 = cell23
    run_ptm_b(F23, E23, r23_, h23, lam23, c23, Wb23, P023, 23, "n23-a%d" % a23)
    # ============================== PTM-C =================================
    ptmc = {}
