        fake = sorted({j * dpm + s for j in range((nn - 1) // dpm + 1) for s in (0, 1)})
        ptmc[nn] = {"Phi_n_irreducible_over_F2(Rabin)": irreducible, "ord_n(2)": ordn, "divisor_degrees": degs,
                    "usable_(2<=l<=n-2)": usable, "IR-3_fires": bool(usable) or ordn != nn - 1,
                    "mutation_pm_order": dpm, "mutation_usable": [dd for dd in fake if 2 <= dd <= nn - 2],
                    "mutation_IR-3_fires": any(2 <= dd <= nn - 2 for dd in fake)}
    OUT["PTM-C"] = ptmc

    # ============================== PTM-D =================================
    F8 = GF2n(3, 0b1011)
    enum = []
    chosen = None
    for a8 in range(8):
        for b8 in range(1, 8):
            E8 = Curve(F8, a8, b8)
