            enum.append((a8, b8, N8))
            if pf and chosen is None:
                chosen = (a8, b8, N8, max(pf))
    a8, b8, N8, r0 = chosen
    E8 = Curve(F8, a8, b8)
    pts8 = [P for x in range(8) for P in E8.points_at_x(x)]
    P8 = next(E8.mul(N8 // r0, P) for P in pts8 if E8.mul(N8 // r0, P) is not None)
    # embed F_8 into F_{2^15} = F_2[w]/(w^15 + w + 1)
    F15 = GF2n(15, (1 << 15) | 3)
    # find beta with beta^3 + beta + 1 = 0
    beta = None
    gen_try = 2
    while beta is None:
        c = F15.pow(gen_try, (2 ** 15 - 1) // 7)
        for i in range(1, 7):
            z = F15.pow(c, i)
            if F15.mul(F15.sq(z), z) ^ z ^ 1 == 0:
                beta = z
                break
        gen_try += 1

    def emb(u):
        acc, pw = 0, 1
        for i in range(3):
            if u >> i & 1:
                acc ^= pw
            pw = F15.mul(pw, beta)
        return acc

    E15 = Curve(F15, emb(a8), emb(b8))
    P15 = (emb(P8[0]), emb(P8[1]))
    assert E15.on(P15) and E15.mul(r0, P15) is None
