    ptmd = {"F8_modulus": "z^3+z+1", "enumeration_order": "(a,b) lexicographic by integer bit pattern, b != 0",
            "first_curve": {"a": a8, "b": b8, "#E(F_8)": N8, "r0": r0}, "P": str(P8),
            "tau_q(P)==P": tau8 == P15, "AR-2_candidates_mod_r0": candsD, "lambda_selected": lamD,
            "AR-2_lambda_ne_1_clause_rejects": lamD == [1],
