            "E1_size_bound_r0>2^7": r0 > 2 ** 7, "E1_r0^2_divides_#E": N15 % (r0 * r0) == 0,
            "E1_largest_prime_factor_r*": rstar, "r*_divides_#E(F_8)": N8 % rstar == 0}
    # what AR-2 says on the r* subgroup if the admission routine recomputes r
