        except AssertionError:
            cs = set()
        lst = [c for c in cs if E15.mul(c, Pst) == E15.frob(Pst, 3)]
        ptmd["recomputed_r*_lambda"] = lst
        ptmd["recomputed_r*_AR-2_pass(lambda^5=1, lambda!=1)"] = bool(lst) and pow(lst[0], 5, rstar) == 1 and lst[0] != 1
        ptmd["recomputed_r*_E1_admits"] = (ptmd["recomputed_r*_AR-2_pass(lambda^5=1, lambda!=1)"]
                                           and N15 % (rstar * rstar) != 0 and rstar > 2 ** 7)
    # mutation: AR-2 with the lambda != 1 clause deleted, plus E1 size bound
    ptmd["mutation_AR2_without_ne1_clause_but_E1_size_bound"] = "rejected by size bound" if r0 <= 2 ** 7 else "admitted"
    # contract definitions.k_and_q applied to the chosen curve's coefficients
    dmin8 = next(dd for dd in (1, 3) if all(F8.frob(c, dd) == c for c in (1, a8, b8)))
    ptmd["k_and_q_rule_on_chosen_curve"] = {"d_min": dmin8, "q": 2 ** dmin8, "k": 15 // dmin8, "k_prime": is_prime(15 // dmin8)}
    tau2 = E15.frob(P15, 1)
