        "lambda^15_mod_r0": [pow(c, 15, r0) for c in lam2], "lambda_ne_1": [c != 1 for c in lam2],
        "ord_lambda": [ord_mod(c, r0) if c else None for c in lam2],
        "AR-2_pass": bool(lam2) and pow(lam2[0], 15 // dmin8, r0) == 1 and lam2[0] != 1}
    ptmd["enumeration_table(a,b,#E(F_8))"] = enum
    # corrected-object variant: first (a, b) with b not in F_2 and a prime factor >= 5
