    dm = next(dd for dd in (1, 3) if all(F8.frob(c, dd) == c for c in (1, aa, bb)))
    qq, kk = 2 ** dm, 15 // dm
    lam_alt = [c for c in range(rr0) if Ealt.mul(c, Palt) == Ealt.frob(Palt, dm)]
    ptmd["corrected_object_variant"] = {"a": aa, "b": bb, "#E(F_8)": NN, "r0": rr0, "d_min": dm, "q": qq, "k": kk,
        "lambda": lam_alt, "AR-2_rejects(lambda=1)": lam_alt == [1],
