    OUT["PTM-D"] = ptmd

    # ==================== rho convention (J4 iii) ==========================
    def log2big(N):
        L = N.bit_length()
        s = max(0, L - 60)
        return s + math.log2(N >> s)
    l_ecc = int("680564733841876926932320129493409985129")
    r233 = int("3450873173395281893717377931138512760570940988862252126328087024741343")
