                     "log2_negation_only_sqrt(pi r/4)": round(neg_only, 4),
                     "net_fall_bits": round(neg_only - conv, 4), "0.5*log2(k)": round(0.5 * math.log2(kk), 4),
                     "superseded_sqrt(2k)_row_for_contrast": round(superseded, 4)}
    rho["ECC2K-130"]["with_Bailey_walk_factor_1.069993"] = round(rho["ECC2K-130"]["log2_rho_sqrt(pi r/(4k))"] + math.log2(1.069993), 4)
    rho["2^129_exact"] = str(2 ** 129)
